import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  // Root container
  const container = new Group();

  // Create local timelines and trackers for cleanup
  const activeTimelines = [];
  const primitiveCleanups = [];

  // Colors from Spec
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10'),
  };

  // 1. Stage Backdrop Card (for depth & contrast)
  // Dimensions fitting a typical thumbnail card (~2.4 x 1.8)
  const cardGeo = new PlaneGeometry(2.4, 1.8);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, -0.1);
  container.add(cardMesh);

  // Subtle Accent Bezel / Rim highlight behind the card
  const bezelGeo = new PlaneGeometry(2.44, 1.84);
  const bezelMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    roughness: 0.2,
    metalness: 0.8,
  });
  const bezelMesh = new Mesh(bezelGeo, bezelMat);
  bezelMesh.position.set(0, 0, -0.12);
  container.add(bezelMesh);

  // Contact Shadow Plane
  const shadowGeo = new PlaneGeometry(2.8, 0.4);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.0, 0);
  container.add(shadowMesh);

  // 2. Accent Lighting (for Hero quality)
  const localKeyLight = new DirectionalLight(colors.accent, 1.2);
  localKeyLight.position.set(-2, 2, 2);
  container.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.paper, 0.8);
  localRimLight.position.set(2, -2, 1);
  container.add(localRimLight);

  // 3. Load Gear Mesh & Apply machined-metal PBR
  let gearMeshGroup = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gearMeshGroup = gltf.scene;

      // Auto-scale and center the gear mesh to fit nicely on our stage card
      gearMeshGroup.scale.setScalar(0.7);
      gearMeshGroup.position.set(0, 0, 0.1);

      gearMeshGroup.traverse((node) => {
        if (node.isMesh) {
          node.material = new MeshPhysicalNodeMaterial({
            color: colors.paper,
            roughness: 0.25,
            metalness: 0.9,
            clearcoat: 0.25,
            clearcoatRoughness: 0.1,
          });
          node.castShadow = true;
          node.receiveShadow = true;
        }
      });

      // Animate gear entry
      gsap.fromTo(
        gearMeshGroup.scale,
        { x: 0, y: 0, z: 0 },
        { x: 0.7, y: 0.7, z: 0.7, duration: 1.0, ease: 'power4.out', delay: 0.1 }
      );

      // Add dynamic subtle continuous rotation to the gear
      const rotTl = gsap.to(gearMeshGroup.rotation, {
        y: Math.PI * 2,
        duration: 20,
        repeat: -1,
        ease: 'none',
      });
      activeTimelines.push(rotTl);

      container.add(gearMeshGroup);
    }).catch((err) => {
      console.error('Failed to load gear mesh:', err);
    });
  }

  // 4. Cinematic Primitives application
  const prim1 = ctx.primitives['parallax-scroll']?.(container, { intensity: 0.4 });
  if (prim1) {
    activeTimelines.push(prim1.timeline);
    primitiveCleanups.push(prim1.cleanup);
  }

  const prim2 = ctx.primitives['magnetic-cursor']?.(container, { radius: 1.2, strength: 0.35 });
  if (prim2) {
    activeTimelines.push(prim2.timeline);
    primitiveCleanups.push(prim2.cleanup);
  }

  // 5. Interactions & Animation (rise-in on hover, emit on click)
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(container.position, {
    y: '+=0.15',
    duration: 0.4,
    ease: 'power3.out',
  });
  hoverTl.to(bezelMesh.scale, {
    x: 1.05,
    y: 1.05,
    duration: 0.4,
    ease: 'power3.out',
  }, 0);

  // Expose pointer handlers through userData.handlers
  container.userData.handlers = {
    pointerenter: () => {
      hoverTl.play();
    },
    pointerleave: () => {
      hoverTl.reverse();
    },
    click: () => {
      // Direct action event
      ctx.emit('hub-features.select', { id: config.id });

      // Punchy click-feedback animation
      const clickTl = gsap.timeline();
      clickTl.to(container.scale, { x: 0.95, y: 0.95, z: 0.95, duration: 0.1, ease: 'power2.out' })
             .to(container.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'elastic.out(1, 0.3)' });
      activeTimelines.push(clickTl);
    }
  };

  // 6. Cleanup Logic
  container.userData.cleanup = () => {
    // Kill all active GSAP animations
    activeTimelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    hoverTl.kill();

    // Call individual primitive cleanup functions
    primitiveCleanups.forEach((cleanup) => {
      if (typeof cleanup === 'function') cleanup();
    });

    // Traverse and dispose geometries and materials
    container.traverse((node) => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((mat) => mat.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return container;
}
